            std::vector<std::pair<std::string, std::string>> entries = {
                {"printer/BedPrinter.json", read_file(printer_json)}, {BUNDLE_STRUCTURE_JSON_NAME, structure.dump()},
                {name, marker}};
            const fs::path zip_file = bed.src / "bad-keyed.orca_printer";
