{
    ScopedTemporaryDir temp_dir;
    ScopedDataDir      data(temp_dir.path());
    const fs::path     user_dir = temp_dir.path() / PRESET_USER_DIR / "default";
    const fs::path     file     = write_user_filament(user_dir, "My PETG", k1_parent);
